/bin/bash -lc "python3 - <<'PY'
from pathlib import Path
text=Path('references.bib').read_text()
entries=[p for p in text.split('\\n\\n') if p.strip()]
print(f'{len(entries)} entries')
for i,e in enumerate(entries,1):
    bal=0
    for ch in e:
        if ch=='{': bal+=1
        elif ch=='}': bal-=1
        if bal<0: raise SystemExit(f'entry {i}: negative brace balance')
    if bal"'!=0: raise SystemExit(f'"'entry {i}: brace balance {bal}')
    if 'CoRR' in e or 'arxiv' in e.lower() or 'journals/corr' in e:
        raise SystemExit(f'entry {i}: arxiv/corr marker found')
print('brace balance ok; no arxiv/corr markers')
PY"

